  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 The Nature of Science and Lab Safety$j$, $j${"readings": [{"title": "Psalm 111 (King James Version)", "url": "/portal/bible/Psalms/111"}], "body": "Science is the careful study of the natural world through observation, measurement and testing. Psalm 111:2 says, The works of the LORD are great, sought out of all them that have pleasure therein. God made an orderly creation, and that order is why careful study works. Genesis 1:1 says, In the beginning God created the heaven and the earth. Scientists ask how things work, and believers can do this work with joy and humility.\n\nScientific work often follows steps like these. Make an observation and ask a question. Form a hypothesis, which is a testable explanation. Design an experiment that changes one factor at a time. The factor you change on purpose is the independent variable. The factor you measure is the dependent variable. The conditions you keep the same are the controls. A control group is the group that does not get the treatment, so that you have something to compare. Collect data, analyze it, draw a conclusion and share the results so that others can repeat the test.\n\nA scientific law describes what happens in nature, often with an equation. A scientific theory is a well tested explanation of why it happens and is supported by a large body of evidence. A theory does not turn into a law. They do different jobs.\n\nSafety is part of good science. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished. Wear goggles and follow your teacher's directions. Never taste or smell unknown chemicals. Tie back long hair, keep your work area clean and know where the eyewash, fire extinguisher and exits are. Tell an adult about every spill or injury right away. First Thessalonians 5:21 says, Prove all things; hold fast that which is good.\n\nYour task: (1) List the steps of a fair experiment. (2) Name the independent variable, dependent variable and controls in an example. (3) State three lab safety rules.\n\nFlorida standards: SC.912.N.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.N.1", "script": "Welcome back. Listen, Psalm 111:2 says, The works of the LORD are great, sought out of all them that have pleasure therein. God made an orderly creation, and that order is why careful study works.\n\nNow watch this. A fair experiment starts with an observation and a question. Then we form a hypothesis, a testable explanation. We change one factor on purpose, the independent variable. We measure the result, the dependent variable. And we keep everything else the same, the controls. A control group gives us something to compare.\n\nLook at the difference between a law and a theory. A law describes what happens, often with an equation. A theory is a well tested explanation of why it happens. A theory does not turn into a law. They do different jobs.\n\nSafety is part of good science. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself. Wear goggles, follow directions, never taste unknown chemicals and report every spill. First Thessalonians 5:21 says, Prove all things; hold fast that which is good.\n\nYour task is to list the steps of a fair experiment, name the variables and state three safety rules. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 The Nature of Science and Lab Safety$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Measurement, SI Units and Scientific Notation$j$, $j${"readings": [{"title": "Proverbs 11 (King James Version)", "url": "/portal/bible/Proverbs/11"}], "body": "Science depends on measurement. Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. Honest, careful measuring is part of integrity.\n\nScientists around the world use the International System of Units, called SI. The base unit of length is the meter, of mass the kilogram, of time the second, and of temperature the kelvin. Volume is often measured in liters. Prefixes change the size of a unit by powers of ten. Kilo means 1000, centi means one hundredth, and milli means one thousandth. So 2.5 kilometers equals 2500 meters, and 350 milliliters equals 0.35 liters. To convert, multiply or divide by the right power of ten, and always write the unit.\n\nVery large and very small numbers are written in scientific notation, a number from 1 up to 10 multiplied by a power of ten. The number 4,500,000 is 4.5 times 10 to the 6th. The number 0.00032 is 3.2 times 10 to the negative 4. The speed of light is about 3.0 times 10 to the 8th meters per second.\n\nGood measurements are accurate and precise. A measurement is accurate if it is close to the true value. It is precise if repeated measurements agree with each other. A scale that always reads 2 grams too high is precise but not accurate. Read an instrument at eye level, include one estimated digit past the smallest mark, and repeat measurements to find an average.\n\nYour task: (1) Convert between metric units. (2) Write a number in scientific notation. (3) Explain the difference between accuracy and precision.\n\nFlorida standards: SC.912.N.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.N.1", "script": "Welcome back. Listen, Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. Honest, careful measuring is part of integrity.\n\nNow watch this. Scientists use the International System of Units, called SI. Length is in meters, mass in kilograms, time in seconds and temperature in kelvins. Prefixes change the size by powers of ten. Kilo is 1000, centi is one hundredth and milli is one thousandth. So 2.5 kilometers is 2500 meters, and 350 milliliters is 0.35 liters.\n\nLook at scientific notation. It is a number from 1 up to 10 times a power of ten. 4,500,000 is 4.5 times 10 to the 6th. 0.00032 is 3.2 times 10 to the negative 4. The speed of light is about 3.0 times 10 to the 8th meters per second.\n\nAccurate means close to the true value. Precise means repeated measurements agree. A scale that always reads 2 grams too high is precise but not accurate. Read at eye level and repeat your measurements.\n\nYour task is to convert units, write scientific notation and explain accuracy and precision. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Measurement, SI Units and Scientific Notation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Properties of Matter and Density$j$, $j${"readings": [{"title": "Isaiah 40 (King James Version)", "url": "/portal/bible/Isaiah/40"}], "body": "Matter is anything that has mass and takes up space. Isaiah 40:12 asks, Who hath measured the waters in the hollow of his hand, and meted out heaven with the span, and comprehended the dust of the earth in a measure, and weighed the mountains in scales, and the hills in a balance? God knows the measure of all matter. We learn to measure it a little at a time.\n\nMass is the amount of matter in an object, measured in kilograms or grams. Weight is the pull of gravity on that mass and is measured in newtons. Your mass stays the same on the Moon, but your weight is smaller. Volume is the space an object takes up. For a box, volume equals length times width times height. For an irregular solid, measure how much water it displaces.\n\nPhysical properties can be observed without changing what the substance is. Examples are color, hardness, melting point, boiling point, conductivity and density. Chemical properties describe how a substance can change into a new substance, such as flammability or the ability to rust.\n\nDensity equals mass divided by volume. A block of aluminum has a mass of 54 grams and a volume of 20 cubic centimeters. Its density is 54 divided by 20, which is 2.7 grams per cubic centimeter. Pure water has a density of about 1.0 gram per cubic centimeter. An object floats in a liquid if it is less dense than the liquid and sinks if it is more dense. Ice has a density of about 0.92 grams per cubic centimeter, so ice floats on water. This unusual property helps lakes freeze from the top down and protects the life beneath.\n\nYour task: (1) Tell the difference between mass and weight. (2) Calculate a density. (3) Predict whether an object floats or sinks in water.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Isaiah 40:12 asks, Who hath measured the waters in the hollow of his hand? God knows the measure of all matter, and we learn to measure it a little at a time.\n\nNow watch this. Matter is anything that has mass and takes up space. Mass is the amount of matter, measured in kilograms. Weight is the pull of gravity on that mass, measured in newtons. Your mass is the same on the Moon, but your weight is smaller. Volume is the space an object takes up.\n\nLook at properties. Physical properties can be observed without changing the substance, such as color, hardness, melting point and density. Chemical properties describe how a substance can change into something new, such as flammability.\n\nDensity is mass divided by volume. A block of aluminum has a mass of 54 grams and a volume of 20 cubic centimeters, so its density is 2.7 grams per cubic centimeter. Water is about 1.0. An object floats if it is less dense than the liquid and sinks if it is more dense. Ice is about 0.92, so ice floats. That helps a lake freeze from the top down and protects the life beneath.\n\nYour task is to tell mass from weight, calculate a density and predict floating or sinking. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Properties of Matter and Density$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 States of Matter and Changes of State$j$, $j${"readings": [{"title": "Psalm 147 (King James Version)", "url": "/portal/bible/Psalms/147"}], "body": "Matter exists in several states. Psalm 147:18 says, He sendeth out his word, and melteth them: he causeth his wind to blow, and the waters flow. The Lord is Lord over ice, water and vapor alike.\n\nThe particle model explains the states. In a solid, particles are packed closely and vibrate in fixed positions, so a solid has a definite shape and volume. In a liquid, particles are close but slide past each other, so a liquid has a definite volume but takes the shape of its container. In a gas, particles are far apart and move freely, so a gas has no definite shape or volume. Plasma is a fourth state, a hot gas of charged particles found in lightning and in stars.\n\nA change of state is a physical change, because the substance is still the same. Melting is solid to liquid. Freezing is liquid to solid. Vaporization is liquid to gas and includes boiling and evaporation. Condensation is gas to liquid. Sublimation is solid directly to gas, as when dry ice fades. Deposition is gas directly to solid, as when frost forms. At sea level, water freezes at 0 degrees Celsius and boils at 100 degrees Celsius. Temperature conversions are kelvins equal degrees Celsius plus 273, so 100 degrees Celsius is 373 kelvins. Energy must be added for melting and vaporization, and energy is released for freezing and condensation.\n\nA chemical change forms new substances. Signs include a new color, bubbles of gas, a solid forming in a liquid, light or heat, and an odor. Burning wood and rusting iron are chemical changes. In every change, mass is conserved. The total mass before equals the total mass after.\n\nYour task: (1) Describe the particles in a solid, liquid and gas. (2) Name each change of state. (3) Tell a physical change from a chemical change.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Psalm 147:18 says, He sendeth out his word, and melteth them: he causeth his wind to blow, and the waters flow. The Lord is Lord over ice, water and vapor alike.\n\nNow watch this. In a solid, particles are packed close and vibrate in place, so a solid keeps its shape and volume. In a liquid, particles slide past each other, so a liquid keeps its volume but takes the shape of its container. In a gas, particles are far apart and move freely. Plasma is a hot gas of charged particles, found in lightning and in stars.\n\nLook at the changes of state. Melting is solid to liquid. Freezing is liquid to solid. Vaporization is liquid to gas. Condensation is gas to liquid. Sublimation is solid straight to gas. Deposition is gas straight to solid. At sea level, water freezes at 0 degrees Celsius and boils at 100. These are physical changes because the substance stays the same.\n\nA chemical change makes new substances. Look for a new color, bubbles, a solid forming, light, heat or an odor. Burning wood is chemical. Mass is conserved in every change.\n\nYour task is to describe the particles in each state, name the changes of state and tell physical from chemical changes. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 States of Matter and Changes of State$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Science, Measurement and Matter$j$, $j${"prompt": "Write a report of at least 250 words on science, measurement and matter. Use complete sentences, show every calculation and label each part. Psalm 111:2 says, The works of the LORD are great, sought out of all them that have pleasure therein.\n\nPart 1: Design a fair experiment to test which brand of paper towel absorbs the most water. Name the question, the hypothesis, the independent variable, the dependent variable and at least three controls.\nPart 2: Convert 4.2 kilometers to meters and 750 milliliters to liters. Write 6,200,000 and 0.00045 in scientific notation.\nPart 3: A metal sample has a mass of 90 grams and a volume of 30 cubic centimeters. Find its density and tell whether it floats or sinks in water, which has a density of 1.0 gram per cubic centimeter.\nPart 4: Describe the particles and the shape and volume of a solid, a liquid and a gas, and name the change of state when each of these happens: ice becomes water, steam becomes water, dry ice becomes gas.\nPart 5: Explain the difference between a physical change and a chemical change with two examples of each, and explain why Proverbs 22:3 applies to lab safety.", "rubric": "100 points. Part 1: 25 points. Part 2: 20 points. Part 3: 20 points. Part 4: 15 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Science, Measurement and Matter$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Wonder and Order$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes something in nature that made you stop and wonder, (2) explains why an orderly creation makes careful measurement and testing possible, (3) explains how honest measuring shows integrity, and (4) connects your answer to Psalm 111:2, Genesis 1:1 or Proverbs 11:1. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a believer study science with both curiosity and humility? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Wonder and Order$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: The Nature of Science and Lab Safety$j$, $j${"questions": [{"q": "A testable explanation that can be supported or rejected by evidence is a:", "options": ["Unit", "Measurement", "Hazard", "Hypothesis"]}, {"q": "The factor that a scientist deliberately changes in an experiment is the:", "options": ["Conclusion", "Dependent variable", "Control group", "Independent variable"]}, {"q": "Which is a safe lab practice?", "options": ["Run in the lab", "Mix unknown chemicals", "Taste chemicals to identify them", "Wear goggles and follow directions"]}, {"q": "A scientific law:", "options": ["Is never tested", "Is an unproven guess", "Is what a theory becomes after enough proof", "Describes what happens in nature, often with an equation"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Nature of Science and Lab Safety$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,3,3}'::int[], array[$j$A hypothesis is a testable explanation.$j$,$j$The independent variable is the one you change.$j$,$j$Goggles and following directions prevent injuries.$j$,$j$Laws describe patterns. Theories explain why.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Nature of Science and Lab Safety$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Measurement, SI Units and Scientific Notation$j$, $j${"questions": [{"q": "The SI base unit of length is the:", "options": ["Meter", "Gram", "Kelvin", "Liter"]}, {"q": "2.5 kilometers equals:", "options": ["2500 meters", "250 meters", "25 meters", "25000 meters"]}, {"q": "4,500,000 written in scientific notation is:", "options": ["0.45 times 10 to the 6th", "45 times 10 to the 6th", "4.5 times 10 to the 5th", "4.5 times 10 to the 6th"]}, {"q": "A measurement that is close to the true value is:", "options": ["Convertible", "Hypothetical", "Accurate", "Variable"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Measurement, SI Units and Scientific Notation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,2}'::int[], array[$j$The meter is the SI unit of length.$j$,$j$Kilo means 1000, so 2.5 times 1000 equals 2500.$j$,$j$Move the decimal 6 places to get 4.5.$j$,$j$Accuracy means closeness to the true value.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Measurement, SI Units and Scientific Notation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Properties of Matter and Density$j$, $j${"questions": [{"q": "Density equals:", "options": ["Mass divided by volume", "Weight plus volume", "Volume divided by mass", "Mass times volume"]}, {"q": "A block has a mass of 54 g and a volume of 20 cubic centimeters. Its density is:", "options": ["34 g per cubic centimeter", "74 g per cubic centimeter", "1.1 g per cubic centimeter", "2.7 g per cubic centimeter"]}, {"q": "Ice floats on liquid water because ice is:", "options": ["More dense than liquid water", "Always lighter in mass", "Less dense than liquid water", "Made of a different substance"]}, {"q": "Which is a physical property?", "options": ["Flammability", "Ability to rust", "Reactivity with acid", "Melting point"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Properties of Matter and Density$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,3}'::int[], array[$j$Density is mass per unit volume.$j$,$j$54 divided by 20 equals 2.7.$j$,$j$Lower density means it floats.$j$,$j$Melting point can be observed without forming a new substance.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Properties of Matter and Density$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: States of Matter and Changes of State$j$, $j${"questions": [{"q": "The change from liquid to gas is called:", "options": ["Freezing", "Condensation", "Vaporization", "Sublimation"]}, {"q": "A solid changing directly into a gas is:", "options": ["Sublimation", "Melting", "Deposition", "Condensation"]}, {"q": "The particles in a gas:", "options": ["Are packed in fixed positions", "Move freely and are far apart", "Do not move", "Slide past each other while touching"]}, {"q": "Which is a chemical change?", "options": ["Boiling water", "Cutting paper", "Burning wood", "Melting ice"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: States of Matter and Changes of State$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,1,2}'::int[], array[$j$Liquid to gas is vaporization.$j$,$j$Sublimation skips the liquid state.$j$,$j$Gas particles are far apart and move freely.$j$,$j$Burning forms new substances.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: States of Matter and Changes of State$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Science, Measurement and Matter$j$, $j${"questions": [{"q": "A fair test changes how many variables at a time?", "options": ["All of them", "Three", "One", "None"]}, {"q": "The SI base unit of mass is the:", "options": ["Liter", "Newton", "Pound", "Kilogram"]}, {"q": "3.2 times 10 to the 3rd equals:", "options": ["320", "32000", "0.0032", "3200"]}, {"q": "350 milliliters equals how many liters?", "options": ["35", "350", "0.35", "3.5"]}, {"q": "A sample has a mass of 120 g and a volume of 40 cubic centimeters. Its density is:", "options": ["80 g per cubic centimeter", "160 g per cubic centimeter", "3 g per cubic centimeter", "0.3 g per cubic centimeter"]}, {"q": "At sea level, water freezes at:", "options": ["0 degrees Celsius", "32 degrees Celsius", "100 degrees Celsius", "273 degrees Celsius"]}, {"q": "A change that forms new substances is:", "options": ["A change of size", "A chemical change", "A change of state", "A physical change"]}, {"q": "Which state of matter has a definite volume but no definite shape?", "options": ["Plasma", "Gas", "Liquid", "Solid"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Science, Measurement and Matter$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,3,2,2,0,1,2}'::int[], array[$j$Change one variable and keep the rest the same.$j$,$j$The kilogram is the SI unit of mass.$j$,$j$Multiplying by 1000 gives 3200.$j$,$j$Milli means one thousandth.$j$,$j$120 divided by 40 equals 3.$j$,$j$Pure water freezes at 0 degrees Celsius.$j$,$j$New substances mean a chemical change.$j$,$j$A liquid takes the shape of its container.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Science, Measurement and Matter$j$ on conflict (item_id) do nothing;
